UPDATE herb SET efficacy = '散瘀止血，消肿定痛', indication = '用于咯血，吐血，衄血，便血，崩漏，外伤出血，胸腹刺痛，跌扑肿痛', description = '三七主产于云南文山，为五加科植物三七的干燥根和根茎。秋季花开前采挖，洗净，分开主根、支根及根茎，干燥。支根习称"筋条"，根茎习称"剪口"。' WHERE id = 1;
UPDATE herb SET efficacy = '养血调经，敛阴止汗，柔肝止痛', indication = '用于头痛眩晕，胁痛，腹痛，四肢挛痛，血虚萎黄，月经不调，自汗，盗汗', description = '白芍主产于安徽亳州、浙江磐安等地，为毛茛科植物芍药的干燥根。夏秋二季采挖，洗净，除去头尾及细根，置沸水中煮后除去外皮或去皮后再煮，晒干。' WHERE id = 2;
UPDATE herb SET efficacy = '补血活血，调经止痛，润肠通便', indication = '用于血虚萎黄，眩晕心悸，月经不调，经闭痛经，虚寒腹痛，风湿痹痛，跌扑损伤，痈疽疮疡，肠燥便秘', description = '当归主产于甘肃岷县、漳县等地，为伞形科植物当归的干燥根。秋末采挖，除去须根及泥沙，待水分稍蒸发后，捆成小把，上棚，用烟火慢慢熏干。' WHERE id = 3;
UPDATE herb SET efficacy = '补气升阳，固表止汗，利水消肿', indication = '用于气虚乏力，食少便溏，中气下陷，久泻脱肛，便血崩漏，表虚自汗，气虚水肿', description = '黄芪主产于甘肃陇西、内蒙古、山西等地，为豆科植物蒙古黄芪或膜荚黄芪的干燥根。春、秋二季采挖，除去须根及根头，晒干。' WHERE id = 4;
UPDATE herb SET efficacy = '补脾益气，清热解毒，祛痰止咳', indication = '用于脾胃虚弱，倦怠乏力，心悸气短，咳嗽痰多，脘腹四肢挛急疼痛，痈肿疮毒', description = '甘草主产于内蒙古、甘肃、新疆等地，为豆科植物甘草的干燥根和根茎。春、秋二季采挖，除去须根，晒干。' WHERE id = 5;
UPDATE herb SET efficacy = '清热解毒，凉散风热', indication = '用于痈肿疔疮，喉痹，丹毒，热毒血痢，风热感冒，温病发热', description = '金银花主产于山东平邑、河南封丘等地，为忍冬科植物忍冬的干燥花蕾或带初开的花。夏初花开放前采收，干燥。' WHERE id = 6;
UPDATE herb SET efficacy = '滋补肝肾，益精明目', indication = '用于虚劳精亏，腰膝酸痛，眩晕耳鸣，阳萎遗精，内热消渴，血虚萎黄，目昏不明', description = '枸杞子主产于宁夏中宁、青海等地，为茄科植物宁夏枸杞的干燥成熟果实。夏、秋二季果实呈红色时采收，热风烘干，除去果梗。' WHERE id = 7;
UPDATE herb SET efficacy = '理气健脾，燥湿化痰', indication = '用于脘腹胀满，食少吐泻，咳嗽痰多', description = '陈皮主产于广东新会等地，为芸香科植物橘及其栽培变种的干燥成熟果皮。采摘成熟果实，剥取果皮，晒干或低温干燥。' WHERE id = 8;
UPDATE herb SET efficacy = '疏散风热，清利头目', indication = '用于风热感冒，头痛', description = '蔓荆子为马鞭草科植物单叶蔓荆的干燥成熟果实。秋季果实成熟时采收，除去杂质，晒干。' WHERE id = 9;
UPDATE herb SET efficacy = '清热凉血，养阴生津', indication = '用于热入营血，温毒发斑，吐血衄血，热病伤阴，舌绛烦渴，津伤便秘', description = '地黄为玄参科植物地黄的干燥根。秋季采挖，除去芦头及须根，洗净，鲜用或干燥。' WHERE id = 10;
UPDATE herb SET efficacy = '大补元气，复脉固脱，补脾益肺', indication = '用于体虚欲脱，气短喘促，自汗肢冷，精神倦怠，食少吐泻', description = '人参为五加科植物人参的干燥根和根茎。多于秋季采挖，洗净后经晒干或烘干。' WHERE id = 11;
UPDATE herb SET efficacy = '活血行气，祛风止痛', indication = '用于胸痹心痛，胸胁刺痛，跌扑肿痛，月经不调，经闭痛经，癥瘕腹痛', description = '川芎为伞形科植物川芎的干燥根茎。夏季当茎上的节盘显著突出并略带紫色时采挖，除去泥沙，晒后烘干，再去须根。' WHERE id = 12;
UPDATE herb SET efficacy = '和解表里，疏肝升阳', indication = '用于感冒发热，寒热往来，胸胁胀痛，月经不调', description = '柴胡为伞形科植物柴胡或狭叶柴胡的干燥根。春、秋二季采挖，除去茎叶及泥沙，干燥。' WHERE id = 13;
UPDATE herb SET efficacy = '宣肺，利咽，祛痰，排脓', indication = '用于咳嗽痰多，胸闷不畅，咽痛音哑，肺痈吐脓', description = '桔梗为桔梗科植物桔梗的干燥根。春、秋二季采挖，洗净，除去须根，趁鲜剥去外皮或不去外皮，干燥。' WHERE id = 14;
UPDATE herb SET efficacy = '清热解毒，凉血利咽', indication = '用于温疫时毒，发热咽痛，温毒发斑，烂喉丹痧', description = '板蓝根为十字花科植物菘蓝的干燥根。秋季采挖，除去泥沙，晒干。' WHERE id = 15;
UPDATE herb SET efficacy = '清热解毒，消痈排脓', indication = '用于肺痈吐脓，痰热喘咳，热痢，热淋', description = '鱼腥草为三白草科植物蕺菜的新鲜全草或干燥地上部分。鲜品全年可采，干品夏季茎叶茂盛花穗多时采割。' WHERE id = 16;
UPDATE herb SET efficacy = '清心豁痰，开窍凉肝', indication = '用于热病神昏，中风痰迷，惊痫抽搐', description = '牛黄为牛科动物牛的干燥胆结石。宰牛时检查胆囊、胆管及肝管，如有结石立即取出，除尽附着的薄膜，阴干。' WHERE id = 17;
UPDATE herb SET efficacy = '燥湿温中，截疟除痰', indication = '用于寒湿内阻，脘腹胀痛，痞满呕吐，疟疾寒热', description = '草豆蔻为姜科植物草豆蔻的干燥近成熟种子。夏、秋二季采收，晒至九成干，或用水略烫，晒至半干，除去果皮，取出种子团，晒干。' WHERE id = 18;
UPDATE herb SET efficacy = '清热泻火，滋阴润燥', indication = '用于外感热病，高热烦渴，肺热咳嗽，骨蒸潮热，内热消渴，肠燥便秘', description = '知母为百合科植物知母的干燥根茎。春、秋二季采挖，除去须根及泥沙，晒干，习称"毛知母"；或除去外皮，晒干。' WHERE id = 19;
UPDATE herb SET efficacy = '泻火除烦，清热利尿', indication = '用于热病心烦，湿热黄疸，血淋涩痛', description = '栀子为茜草科植物栀子的干燥成熟果实。9-11月果实成熟呈红黄色时采收，除去果梗及杂质，蒸至上气或置沸水中略烫，取出，干燥。' WHERE id = 20;
UPDATE herb SET efficacy = '散风清热，平肝明目', indication = '用于风热感冒，头痛眩晕，目赤肿痛，眼目昏花', description = '菊花为菊科植物菊的干燥头状花序。秋冬季采收，除去枝叶，蒸晒干燥。' WHERE id = 21;
UPDATE herb SET efficacy = '活血通经，散瘀止痛', indication = '用于经闭，痛经，恶露不行，癥瘕痞块，跌扑损伤，疮疡肿痛', description = '红花为菊科植物红花的干燥花。夏季花冠由黄变红时采摘，阴干或晒干。' WHERE id = 22;
UPDATE herb SET efficacy = '化湿开胃，温脾止泻', indication = '用于湿浊中阻，脘痞不饥，脾胃虚寒，呕吐泄泻', description = '砂仁为姜科植物阳春砂或海南砂的干燥成熟果实。夏、秋间果实成熟时采收，晒干或低温干燥。' WHERE id = 23;
UPDATE herb SET efficacy = '清热解毒，疏散风热', indication = '用于痈肿疔疮，喉痹，丹毒，热毒血痢，风热感冒，温病发热', description = '连翘为木犀科植物连翘的干燥果实。秋季果实初熟尚带绿色时采收，除去杂质，蒸熟，晒干，习称"青翘"；果实熟透时采收，晒干，习称"老翘"。' WHERE id = 24;
UPDATE herb SET efficacy = '宣散风热，清头目', indication = '用于风热感冒，头痛，咽喉肿痛', description = '牛蒡子为菊科植物牛蒡的干燥成熟果实。秋季果实成熟时采收果序，晒干，打下果实，除去杂质，再晒干。' WHERE id = 25;
UPDATE herb SET efficacy = '疏散风热，清利头目', indication = '用于风热感冒，头痛，咽喉肿痛', description = '薄荷为唇形科植物薄荷的干燥地上部分。夏、秋二季茎叶茂盛或花开至三轮时，选晴天分次采割，晒干或阴干。' WHERE id = 26;
UPDATE herb SET efficacy = '化湿醒脾，辟秽和中', indication = '用于湿浊中阻，脘痞呕吐，暑湿倦怠，胸闷不舒', description = '藿香为唇形科植物广藿香的干燥地上部分。枝叶茂盛时采割，日晒夜闷，反复至干。' WHERE id = 27;
UPDATE herb SET efficacy = '燥湿健脾，祛风散寒', indication = '用于湿阻中焦，脘腹胀满，泄泻，水肿，脚气痿躄，风湿痹痛', description = '苍术为菊科植物茅苍术或北苍术的干燥根茎。春、秋二季采挖，除去泥沙，晒干，撞去须根。' WHERE id = 28;
UPDATE herb SET efficacy = '利水渗湿，健脾宁心', indication = '用于水肿尿少，痰饮眩悸，脾虚食少，便溏泄泻，心神不安，惊悸失眠', description = '茯苓为多孔菌科真菌茯苓的干燥菌核。多于7-9月采挖，挖出后除去泥沙，堆置"发汗"后，摊开晾至表面干燥，再"发汗"，反复数次至现皱纹、内部水分大部散失后，阴干。' WHERE id = 29;
UPDATE herb SET efficacy = '利水渗湿，泄热', indication = '用于小便不利，水肿胀满，泄泻尿少，痰饮眩晕，热淋涩痛', description = '泽泻为泽泻科植物泽泻的干燥块茎。冬季茎叶开始枯萎时采挖，洗净，干燥，除去须根及粗皮。' WHERE id = 30;

INSERT INTO news (title, summary, content, cover_image, category, tags, author, source, view_count, published_at) VALUES
('2026年中药材出口形势分析：机遇与挑战并存', '随着全球对中医药认可度提升，中药材出口呈现新格局', '<p>2026年，随着世界卫生组织对传统医学的持续推广，以及"一带一路"倡议的深入推进，中药材出口迎来了新的发展机遇。据海关总署最新数据，2025年我国中药材及饮片出口额达18.6亿美元，同比增长12.3%。</p><p>从出口品种来看，枸杞、人参、当归、黄芪等滋补类药材需求持续增长，特别是东南亚和欧美市场对有机中药材的需求旺盛。同时，日韩市场对高品质道地药材的采购量也在稳步提升。</p><p>然而，挑战同样不容忽视。国际质量标准日益严格，农残、重金属限量标准不断提高，部分出口企业面临技术壁垒。此外，国际市场竞争加剧，韩国、日本等国的汉方药企也在积极抢占市场份额。</p><p>专家建议，中药材出口企业应加强源头管控，建立可追溯体系，提升产品品质；同时积极申请国际认证，拓展多元化市场，降低对单一市场的依赖。</p>', '', '药市动态', '出口,贸易', '编辑部', '中药材天地网', 128, '2026-05-13 10:00:00'),
('黄芪价格持续走高，产地货源趋紧', '甘肃陇西黄芪产新量减少，市场供应偏紧推动价格上涨', '<p>近期，甘肃陇西黄芪走货加快，价格持续走高。据市场监测数据显示，黄芪统货价格已从月初的14元/公斤上涨至目前的16元/公斤，涨幅达14.3%。</p><p>分析人士指出，本轮黄芪价格上涨主要受以下因素影响：一是去年主产区甘肃遭遇干旱天气，黄芪单产下降约20%；二是近年黄芪种植面积有所缩减，市场库存持续消化；三是药企采购需求稳定增长，特别是配方颗粒和中药注射剂对黄芪原料的需求旺盛。</p><p>从产地反馈来看，目前陇西黄芪产新已基本结束，新货上市量有限，持货商惜售心理较强。预计短期内黄芪价格仍将维持偏强走势，但需关注后续药企采购节奏的变化。</p>', '', '品种分析', '黄芪,价格', '市场分析部', '药通网', 256, '2026-05-12 14:30:00'),
('中药材种子种苗标准化建设加快推进', '农业农村部发布中药材种子种苗标准体系规划', '<p>近日，农业农村部联合国家中医药管理局发布了《中药材种子种苗标准体系建设规划（2026-2030年）》，标志着我国中药材种业发展进入标准化、规范化新阶段。</p><p>规划提出，到2030年，要制定完成200种以上大宗中药材种子种苗质量标准，建立完善的中药材品种审定和登记制度，建设50个中药材良种繁育基地，良种覆盖率提升至60%以上。</p><p>业内专家表示，中药材种子种苗是中药材质量的源头，长期以来存在品种混乱、质量参差不齐等问题，严重影响了中药材的道地性和临床疗效。此次规划的出台，将有力推动中药材种业高质量发展，为中药材产业提质增效奠定基础。</p>', '', '政策', '种子,标准化,政策', '政策研究部', '中国中医药报', 89, '2026-05-11 09:00:00'),
('当归产新季来临，岷县产地调研报告', '甘肃岷县当归产新即将开始，产地长势及市场预期分析', '<p>5月中旬，甘肃岷县即将迎来当归产新季。记者深入岷县当归主产区调研发现，今年当归整体长势良好，但种植面积较去年有所调整。</p><p>据岷县农业农村局统计，2026年岷县当归种植面积约8.2万亩，较去年减少约5%。种植面积缩减的主要原因是部分农户改种经济效益更高的党参和黄芪。</p><p>从田间长势来看，今年岷县降水较为充沛，当归植株生长健壮，病虫害发生率较低，预计单产将高于去年。但受种植面积减少影响，总产量可能与去年基本持平或略有下降。</p>', '', '产地', '当归,岷县,产新', '产地记者', '中药材天地网', 342, '2026-05-10 16:00:00'),
('金银花产新在即，供需格局如何演变', '山东平邑金银花产新临近，市场关注新花产量及价格走势', '<p>山东平邑金银花产新即将于5月下旬开始，市场对今年金银花产量和价格走势高度关注。</p><p>据平邑县金银花协会预计，2026年平邑金银花种植面积与去年基本持平，约38万亩。从目前花蕾发育情况看，今年金银花长势良好，若后期无极端天气影响，预计产量将达1.8万吨左右，与去年相当。</p><p>需求方面，金银花作为清热解毒类代表药材，在感冒类中成药和凉茶饮料中用量巨大。近年来，随着金银花提取物在保健品和化妆品领域的应用拓展，市场需求持续增长。</p>', '', '品种分析', '金银花,产新', '市场分析部', '药通网', 198, '2026-05-09 11:00:00'),
('中医药法实施成效显著，中药材质量稳步提升', '中医药法实施以来中药材质量抽检合格率持续提高', '<p>国家药监局近日发布的2025年度中药材质量抽检报告显示，中药材抽检合格率达到93.2%，较中医药法实施前提高了12个百分点，中药材质量稳步提升。</p><p>报告指出，近年来通过加强道地药材基地建设、推行中药材GAP种植、强化市场流通监管等综合措施，中药材质量状况持续改善。其中，三七、当归、黄芪等大宗道地药材的合格率均超过95%。</p>', '', '政策', '质量,监管', '政策研究部', '中国中医药报', 156, '2026-05-08 10:00:00'),
('白芍行情低迷，后市何去何从', '安徽亳州白芍供大于求，价格持续走低', '<p>近期，安徽亳州白芍市场行情持续低迷，统货价格已跌至10元/公斤以下，创下近三年新低。</p><p>白芍此轮下跌行情始于2025年下半年，主要原因是前几年白芍价格较高，刺激了种植面积大幅扩张。据统计，2024-2025年亳州白芍种植面积较2022年增长约40%，导致产新后市场供应严重过剩。</p><p>分析人士认为，白芍行情短期内难以好转，预计低价行情还将持续1-2年，直到种植面积调整到位、库存消化至合理水平。</p>', '', '品种分析', '白芍,行情', '市场分析部', '中药材天地网', 276, '2026-05-07 15:00:00'),
('中药材电商发展迅猛，线上交易额突破千亿', '2025年中药材线上交易额达1200亿元，同比增长35%', '<p>随着数字经济的快速发展，中药材电商呈现爆发式增长。据中国中药协会统计，2025年中药材线上交易额突破1200亿元，同比增长35%，占中药材总交易额的比重提升至25%。</p><p>目前，中药材电商平台已形成以B2B为主、B2C为辅的格局。其中，中药材天地网、药通网等垂直平台占据B2B市场主导地位，而天猫、京东等综合电商平台则在零售端表现突出。</p>', '', '药市动态', '电商,数字化', '编辑部', '中药材天地网', 203, '2026-05-06 09:30:00');

